def load_routes() -> Tuple[Dict[int, List[Dict]], Dict[Tuple[str, ...], int]]:
    """Decompress and construct routes and shop route mapping."""
    data = json.loads(zlib.decompress(base64.b85decode(_R108_DATA_B85)))
    routes = {
        int(k): [data['actions'][i] for i in ids]
        for k, ids in data['routes'].items()
    }
    shop_routes = {
        tuple(r['shops']): r['route']
        for r in data['shops']
    }
    return routes, shop_routes
